use std::rc::Rc;use std::cell::RefCell;impl Solution{pub fn binary_tree_paths(root:Option<Rc<RefCell<TreeNode>>>)->Vec<String>{fn f(n:&Option<Rc<RefCell<TreeNode>>>,s:String,o:&mut Vec<String>){if let Some(x)=n{let b=x.borrow();let s=if s.is_empty(){b.val.to_string()}else{format!("{}->{}",s,b.val)};if b.left.is_none()&&b.right.is_none(){o.push(s)}else{f(&b.left,s.clone(),o);f(&b.right,s,o)}}}let mut o=vec![];f(&root,String::new(),&mut o);o}}
